from pathlib import Path
from html import escape
notice='This is a fictional website created for educational purposes as part of MKTG:4400 at the University of Iowa. It is not a real business.'
nav=[('Home','index.html'),('Parking','parking.html'),('Food & Dining','food.html'),('Tailgating & Traditions','traditions.html')]
def card(tag,title,desc,link=None,label=None):
 return f'<article class="card"><span class="tag">{tag}</span><h3>{title}</h3><p>{desc}</p>'+ (f'<a href="{link}">{label or "Explore guide"} →</a>' if link else '')+'</article>'
def render(filename,title,desc,body,home=False):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if filename==url else '')+f'>{label}</a>' for label,url in nav)
 head=(f'<section class="hero"><div class="eyebrow">Your Iowa City weekend starts here</div><h1>{title}</h1><p>{desc}</p><a class="button" href="parking.html">Start planning your visit →</a></section>' if home else f'<section class="pagehead"><div class="inner"><div class="eyebrow">Iowa City Game Day Guide</div><h1>{title}</h1><p>{desc}</p></div></section>')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Iowa City Game Day Guide</title><meta name="description" content="{escape(desc)}"><link rel="stylesheet" href="style.css"></head><body><div class="notice">{notice}</div><header><a class="brand" href="index.html">IOWA CITY <span style="color:white">GAME DAY GUIDE</span></a><nav aria-label="Main navigation">{links}</nav></header>{head}<main>{body}</main><footer><p>{notice}</p><p>Explore: <a href="index.html">Home</a> · <a href="parking.html">Parking</a> · <a href="food.html">Food</a> · <a href="traditions.html">Traditions</a></p><p>Student educational project · Not affiliated with the University of Iowa Athletics Department.</p></footer></body></html>'''
 Path(filename).write_text(html,encoding='utf-8')
render('index.html','Make Every Iowa Football Game Day Count','A simple planning guide for first-time visitors, students, families, and friends heading to Iowa City for a football weekend.',f'''<section class="container"><h2>Plan the day, not just the game.</h2><p class="lead">A great football weekend starts before kickoff. Use these guides to think through your arrival, your meal plans, and the traditions that make the atmosphere memorable.</p><div class="grid">{card('01 · Get there','Parking & Transportation','Explore arrival strategies, walking routes, and parking preparation near Kinnick Stadium.','parking.html','Plan your parking')}{card('02 · Eat well','Food & Dining','Choose the kind of pregame or postgame meal that fits your group and schedule.','food.html','Explore dining ideas')}{card('03 · Join in','Tailgating & Traditions','Get familiar with the game day atmosphere, tailgating etiquette, and the Iowa Wave.','traditions.html','Discover traditions')}</div><div class="tip"><strong>First-time visitor tip:</strong> Build your schedule backward from kickoff. Leave room for traffic, walking, stadium entry, and unexpected delays.</div><h2>Build a flexible game day plan</h2><p>Start by checking the official kickoff time and current stadium policies. Next, pick your arrival plan, decide when you want to eat, and leave time to enjoy the atmosphere. Treat this guide as a planning starting point rather than a source of live event information.</p></section>''',True)
render('parking.html','Kinnick Stadium Parking & Transportation','Prepare for your Iowa football visit with parking research tips, arrival planning, and ways to get around Iowa City.',f'''<section class="container"><h2>Choose your arrival strategy</h2><p class="lead">Parking availability, access restrictions, and traffic patterns can vary by game. Check current official information before choosing a lot or route.</p><div class="grid">{card('Option 1','Prearranged parking','If you have a reserved space or parking pass, confirm the entrance, arrival window, and any game-day restrictions before leaving.')}{card('Option 2','Park and walk','Consider whether a legal parking location farther from the stadium offers a more comfortable arrival. Review walking distance and accessibility.')}{card('Option 3','Drop-off or transit','Research current public transportation, rideshare, and designated drop-off options. Do not assume ordinary pickup points remain open on game day.')}</div><h2>Before you drive</h2><p>Look up the current stadium parking map, check road closures, and save the location of your parking area. Give yourself extra time for crowds and keep your return route in mind.</p><div class="tip"><strong>Verify current details:</strong> Consult <a href="https://hawkeyesports.com/" target="_blank" rel="noopener noreferrer">Iowa Athletics</a> and <a href="https://transportation.uiowa.edu/" target="_blank" rel="noopener noreferrer">University of Iowa Transportation</a> for official updates. This educational site does not publish verified lot inventory or prices.</div><p>Still planning your day? Find <a href="food.html">food near the stadium</a> or explore <a href="traditions.html">tailgating and traditions</a>.</p></section>''')
render('food.html','Iowa City Game Day Food & Dining','Find a dining strategy for before or after an Iowa football game, from quick bites to a relaxed group meal.',f'''<section class="container"><h2>Eat on your schedule</h2><p class="lead">The best food plan depends on your arrival time, group size, and how much time you want to spend near the stadium.</p><div class="grid">{card('Before kickoff','Quick breakfast or coffee','For an early start, look for a convenient breakfast or coffee stop. Check opening hours and allow time for lines.')}{card('Pregame meal','Sit-down lunch','If your group wants to gather before the game, choose a restaurant that fits your route and check whether reservations are offered.')}{card('After the game','Postgame dinner','A meal after the final whistle can be a comfortable way to wait out crowds. Check kitchens’ closing times and travel plans.')}</div><h2>How to choose a restaurant</h2><p>Compare distance from your parking area, menu variety, expected wait times, and dietary needs. Downtown Iowa City and the areas surrounding campus can be useful starting points for exploring dining options.</p><div class="tip"><strong>Planning tip:</strong> Hours, menus, and availability can change on football weekends. Confirm all details directly with a restaurant before making plans.</div><p>Coordinate your meal with your <a href="parking.html">parking and arrival plan</a>, then read about <a href="traditions.html">game day traditions</a>.</p></section>''')
render('traditions.html','Iowa Football Tailgating & Traditions','Get ready for the atmosphere around Kinnick Stadium with tailgating planning tips and an introduction to the Iowa Wave.',f'''<section class="container"><h2>Be part of the atmosphere</h2><p class="lead">A game day can be more than the action on the field. Fans gather with friends and family, wear black and gold, and share traditions that shape the experience.</p><div class="grid">{card('Tradition','The Iowa Wave','At the end of the first quarter, fans at Kinnick Stadium turn toward the nearby children’s hospital and wave in a shared gesture of support.')}{card('Pregame','Tailgating together','Plan food, water, weather-ready clothing, and a meeting point. Follow all current university and parking-area policies.')}{card('Inside Kinnick','Cheering with the crowd','Wear your colors, arrive in time to find your seat, and enjoy the energy of the stadium while respecting fellow fans.')}</div><h2>A simple first-timer checklist</h2><p>Confirm the kickoff time, check the forecast, review current stadium entry and bag policies, and decide where to meet your group. If you are tailgating, verify which activities are permitted in your chosen location.</p><div class="tip"><strong>Remember:</strong> Rules and schedules can change. Use <a href="https://hawkeyesports.com/" target="_blank" rel="noopener noreferrer">Iowa Athletics</a> for current event information.</div><p>Need to coordinate the rest of your day? Review <a href="parking.html">parking options</a> and <a href="food.html">dining ideas</a>.</p></section>''')
